import"./chunk-2NFLSA4Y.js";var t={spacetimeCurvature:{theory:{concept:"[[General relativity (Einstein, 1915) describes gravity not as an ordinary force but as the curvature of spacetime produced by mass and energy.]] Freely moving bodies and light follow the straightest possible paths (geodesics) in this curved spacetime, and that is what we see as falling and orbiting. In weak fields the theory gives the same results as Newton's law of gravitation. The rotating globe and the sunken grid here are only an analogy for curvature: the numerical readings use Newtonian gravity for a spherical body, and the grid shape is not a solution of Einstein's equations."},section:{spacetime:{title:"What the drawing does not show",text:"[[Spacetime includes time as well as space; this drawing shows neither the full four-dimensional geometry nor how time changes.]]"},sheet:{title:"What the grid means",text:"The drawn grid is a two-dimensional surface lowered in a third direction so curvature is easy to see. [[The down direction is an artistic device, not a real direction of gravitational pull.]] Changing mass or radius exaggerates the dip for visibility."},gravity:{title:"Numbers beside the picture",text:"For a spherical body of mass M and radius R, Newton's approximation gives surface gravity g = GM/R\xB2 and escape speed v\u2091 = \u221A(2GM/R). Doubling mass at fixed radius doubles g; doubling radius at fixed mass divides g by four."},limits:{title:"Where the analogy stops",text:"[[The rubber-sheet picture cannot explain gravity by itself: a ball rolling into a dip would already need gravity.]] It also leaves out curved time, light paths and strong-field effects. Use the black-hole topic for a quantitative result from general relativity."},evidence:{title:"Is it really true?",text:"General relativity has passed every test so far. Starlight passing the Sun is bent \u2014 first measured during the solar eclipse of 1919, today with radio telescopes to better than 0.1 %. Clocks higher up run faster: the clocks on GPS satellites gain about 38 microseconds a day on clocks on the ground, and without correcting for this, satnav positions would drift by about 10 km a day. In 2015, a hundred years after Einstein predicted them, the LIGO detectors measured gravitational waves \u2014 ripples of spacetime itself \u2014 from two merging black holes."},try:{title:"Try it",text:"Increase mass while keeping radius fixed, then increase radius while keeping mass fixed. Watch the illustrative grid and compare the measured gravity and escape speed. Drag to rotate the 3D view."}},formula:{gravity:"Newtonian surface gravity of a spherical body",escape:"Newtonian escape speed from its surface"},variable:{mass:"Body mass",radius:"Body radius",gravity:"Surface gravitational acceleration"},assumption:{sheet:"The grid is a deliberately exaggerated rubber-sheet analogy, not a spacetime metric or a to-scale picture. Its depth is only a visual cue and is not used in the numerical calculations.",newtonian:"The displayed gravity and escape speed use Newtonian formulas, appropriate as an approximation for ordinary planets. They are not predictions from the grid shape.",body:"The body is treated as spherical and nonrotating, with no atmosphere or tidal effects. Globe rotation in the animation is decorative."},param:{massEarth:"Mass (Earth masses)",radiusEarth:"Radius (Earth radii)",duration:"Animation duration",timeStep:"Simulation timestep"},hint:{massEarth:"1 means one Earth mass. The visual dip is intentionally exaggerated.",radiusEarth:"1 means one Earth radius. The model computes gravity at the surface."},measure:{surfaceGravity:"Surface gravity",escapeSpeed:"Escape speed"},visual:{sheet:"Curvature analogy grid"},view:{body:"Spherical body",analogy:"Illustrative grid \xB7 not to scale"},challenge:{double:{title:"Stronger gravity",description:"Make surface gravity at least 19 m/s\xB2.",hint:"Try doubling mass without changing radius."},weak:{title:"Weaker gravity",description:"Reduce surface gravity below 3 m/s\xB2.",hint:"Increase radius while keeping mass near one Earth mass."},escape:{title:"Fast escape",description:"Reach an escape speed of at least 20 km/s.",hint:"Raise mass and lower radius."}}}},i={sim:t};export{i as default,t as sim};
